class SendReceipt implements ShouldQueue
{
    use Queueable, SerializesModels;

    public int $tries = 5;
    public array $backoff = [30, 120, 600, 1800];   // seconds between attempts
    public int $timeout = 60;

    public function __construct(public readonly int $orderId) {}   // id, not model

    public function middleware(): array
    {
        return [new WithoutOverlapping($this->orderId), new RateLimited('mailer')];
    }

    public function handle(Mailer $mailer): void
    {
        $order = Order::findOrFail($this->orderId);
        if ($order->receipt_sent_at) {                 // idempotent: safe to run twice
            return;
        }
        $mailer->to($order->user)->send(new ReceiptMail($order));
        $order->update(['receipt_sent_at' => now()]);
        // let exceptions propagate — that's how retries and failed_jobs work
    }

    public function failed(\Throwable $e): void
    {
        Log::critical('Receipt failed permanently', ['order' => $this->orderId, 'error' => $e->getMessage()]);
        // alert / mark for manual follow-up
    }
}

// separate concerns: CRM sync is its own job with its own retry policy
DB::transaction(function () use ($data) {
    $order = Order::create($data);
    Bus::chain([
        new SendReceipt($order->id),
        new SyncOrderToCrm($order->id),
    ])->dispatch()->afterCommit();   // or SendReceipt::dispatch($order->id)->afterCommit()
});

