class GenerateInvoicePdf implements ShouldQueue {
    use Queueable;
    public int $tries = 3;
    public array $backoff = [5, 10];
    public function __construct(public readonly int $orderId) {}
    public function handle(): void {
        $n = Cache::increment("pdf-attempts:{$this->orderId}");
        if ($n < 3) throw new \RuntimeException("simulated failure #{$n}");
        Log::info("PDF generated for {$this->orderId} on attempt {$n}");
    }
    public function failed(\Throwable $e): void { Log::error('PDF failed permanently: '.$e->getMessage()); }
}
// php artisan tinker → GenerateInvoicePdf::dispatch(1);
// php artisan queue:work --verbose   (watch: Processing → Failed → wait 5s → Failed → wait 10s → Processed)
// SELECT id, attempts, available_at FROM jobs;   between attempts shows the delay
// With $tries = 2: SELECT * FROM failed_jobs;  then  php artisan queue:retry all

public function middleware(): array { return [new WithoutOverlapping($this->orderId)]; }

public function handle(): void {
    $order = Order::findOrFail($this->orderId);
    if ($order->invoice_pdf_generated_at) return;          // idempotent check
    // ... generate ...
    $order->update(['invoice_pdf_generated_at' => now()]);
}

// Dispatch twice → log shows one 'generated'. Without WithoutOverlapping, two workers could both pass the check
// before either writes generated_at (the read-then-write race from the transactions module). WithoutOverlapping
// takes a cache lock keyed by orderId so the second job waits or is released.

// Four independent side effects → four jobs, each with its own retry policy. Nothing depends on another, so no chain.
Bus::batch([
    new SendReceipt($order->id),           // tries 5, backoff [30,120,600]
    new SyncOrderToCrm($order->id),        // retryUntil(now()->addHours(6)), backoff [60,300,900,1800]
    new NotifyWarehouse($order->id),       // tries 3, high queue
    new RecordOrderAnalytics($order->id),  // tries 1 — best effort, low queue
])->allowFailures()->dispatch()->afterCommit();

// CRM down for an hour: SyncOrderToCrm keeps retrying with growing gaps for up to 6 hours; nothing else is blocked
// because it is its own job on its own queue. Visibility: Horizon dashboard (wait time, failed), an alert when
// failed_jobs grows or when a job's age exceeds N minutes, and the CRM job's failed() posting to Slack.
// If they were dependent (e.g. warehouse needs the CRM id) → Bus::chain in that order.
